/**
 * Settings — user-facing preferences ONLY.
 *
 * Apple iOS-style: each feature gets its own collapsible section + a grouped
 * card of single-row controls. No descriptive paragraphs, no nested cards.
 *
 * Operationally sensitive controls (backend env, URL overrides) live in the
 * admin-gated Debug tab. A regular user MUST NOT be able to repoint the
 * extension at staging / dev / localhost from here.
 */

import { OpenUrl } from '@/components/OpenUrl';
import { Collapsible } from '@/components/ui/collapsible';
import { ENV } from '@/config/env';
import { AdvancedAgentCapabilities } from '@/features/settings/AdvancedAgentCapabilities';
import { useActiveOrganization } from '@/hooks/use-active-organization';
import { useAuth } from '@/hooks/use-auth';
import { useDesktopBridge } from '@/hooks/use-desktop';
import { getEnginePortOverride, setEnginePortOverride } from '@/lib/desktop/discovery';
import { clearPairToken, setPairToken } from '@/lib/desktop/http';
import {
  desktopStatusTextClass,
  engineHealthState,
  formatDesktopConnectionLabel,
} from '@/lib/desktop/types';
import { confirmDestructive } from '@/lib/destructive/confirm';
import { DEFAULT_CHAT_MANDATE_KEY } from '@/lib/mandates';
import { send } from '@/lib/messaging/native';
import { CHANNELS } from '@/lib/messaging/schemas';
import { retrySettingsSave, useSettingsSaveState } from '@/lib/settings/persistence';
import { cn } from '@/lib/utils';
import { useSettingsStore } from '@/state/settings';
import { AgentListDropdown } from '@ai-matrx/agents/catalog/react';
import { ConfirmDialog } from '@ai-matrx/design-system';
import {
  ArchiveFilter,
  type ArchiveFilterValue,
  Button,
  DEFAULT_ARCHIVE_FILTER,
  BasicInput as Input,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@ai-matrx/design-system';
import { Switch } from '@ai-matrx/design-system';
import { ChevronRight, LogIn, LogOut, Trash2 } from 'lucide-react';
import { useCallback, useEffect, useRef, useState } from 'react';

const NONE = '__none__';

function serializeStorageWrite(
  pending: { current: Promise<void> },
  write: () => Promise<void>,
): Promise<void> {
  const result = pending.current.then(write);
  pending.current = result.then(
    () => undefined,
    () => undefined,
  );
  return result;
}

type ExtensionUpdateStatus =
  | { kind: 'idle' }
  | { kind: 'no_update' }
  | { kind: 'update_available'; version?: string }
  | { kind: 'throttled' }
  | { kind: 'error' };

type BrowserLoginApiAvailability = 'available' | 'unavailable';

function installedBrowserLabel(): string {
  const userAgent = navigator.userAgent;
  if (userAgent.includes('Edg/')) return 'Microsoft Edge';
  if (userAgent.includes('OPR/')) return 'Opera';
  if (userAgent.includes('Firefox/')) return 'Firefox';
  if (userAgent.includes('CriOS/') || userAgent.includes('Chrome/')) return 'Chrome';
  if (userAgent.includes('Safari/')) return 'Safari';
  return 'This browser';
}

function browserLoginApiAvailability(): BrowserLoginApiAvailability {
  const runtime = chrome.runtime;
  const canUsePasswordFlow =
    typeof runtime?.sendMessage === 'function' &&
    typeof chrome.tabs?.get === 'function' &&
    typeof chrome.scripting?.executeScript === 'function' &&
    typeof chrome.storage?.local?.get === 'function';
  return canUsePasswordFlow ? 'available' : 'unavailable';
}

function updateStatusCopy(status: ExtensionUpdateStatus): string | null {
  switch (status.kind) {
    case 'no_update':
      return 'Your browser did not find an update right now.';
    case 'update_available':
      return status.version
        ? `Version ${status.version} is available. Open your browser’s Extensions page, find Matrx Extend, and use its update controls to finish the update.`
        : 'An update is available. Open your browser’s Extensions page, find Matrx Extend, and use its update controls to finish the update.';
    case 'throttled':
      return 'Your browser limited update checks. Try again later, or use its Extensions page to review updates.';
    case 'error':
      return 'Could not check right now. Open your browser’s Extensions page, find Matrx Extend, and use its update controls.';
    case 'idle':
      return null;
  }
}

export function SettingsView() {
  const { user, signIn, signOut, isAdmin } = useAuth();
  const desktop = useDesktopBridge();
  const settings = useSettingsStore();
  const settingsSaveState = useSettingsSaveState();
  const [pairTokenInput, setPairTokenInput] = useState('');
  const [pairTokenError, setPairTokenError] = useState<string | null>(null);
  const pairWritePending = useRef(Promise.resolve());
  const pairInputRevision = useRef(0);
  const [enginePortInput, setEnginePortInput] = useState('');
  const [enginePortSaved, setEnginePortSaved] = useState<number | null>(null);
  const [enginePortError, setEnginePortError] = useState<string | null>(null);
  const enginePortWritePending = useRef(Promise.resolve());
  const enginePortInputRevision = useRef(0);
  const [clearLocalDataOpen, setClearLocalDataOpen] = useState(false);
  const [clearLocalDataError, setClearLocalDataError] = useState<string | null>(null);
  const [extensionUpdate, setExtensionUpdate] = useState<ExtensionUpdateStatus>({ kind: 'idle' });
  const [orgArchiveFilter, setOrgArchiveFilter] =
    useState<ArchiveFilterValue>(DEFAULT_ARCHIVE_FILTER);
  // Which organization this install acts in. Every backend request and every
  // organization-scoped write carries it, so a user with more than one
  // organization must state which one before the extension can do anything.
  const org = useActiveOrganization(orgArchiveFilter);
  const [orgError, setOrgError] = useState<string | null>(null);
  const activeOrganizations = org.organizations.filter((organization) => !organization.archivedAt);
  const archivedOrganizations = org.organizations.filter(
    (organization) => !!organization.archivedAt,
  );

  useEffect(() => {
    let cancelled = false;
    const inputRevision = enginePortInputRevision.current;
    const initialRead = getEnginePortOverride();
    enginePortWritePending.current = initialRead.then(
      () => undefined,
      () => undefined,
    );
    void (async () => {
      try {
        const p = await initialRead;
        if (cancelled) return;
        setEnginePortSaved(p);
        if (enginePortInputRevision.current === inputRevision)
          setEnginePortInput(p === null ? '' : String(p));
      } catch {
        if (!cancelled)
          setEnginePortError('Could not load saved port. Reopen Settings to try again.');
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  const handleSaveEnginePort = async () => {
    const trimmed = enginePortInput.trim();
    const n = Number(trimmed);
    if (trimmed !== '' && (!Number.isInteger(n) || n < 1 || n > 65535)) {
      // Silent return left the input showing a value that was never applied.
      setEnginePortError('Port must be 1–65535.');
      return;
    }
    const nextPort = trimmed === '' ? null : n;
    try {
      await serializeStorageWrite(enginePortWritePending, () => setEnginePortOverride(nextPort));
    } catch {
      setEnginePortError('Could not save port. Try again.');
      return;
    }
    setEnginePortSaved(nextPort);
    setEnginePortError(null);
    // The worker owns discovery state and the socket. A rediscovery failure
    // does not undo a successfully persisted port choice.
    await send(CHANNELS.DESKTOP_REDISCOVER, {}).catch(() => undefined);
  };

  const handleClearLocalDataConfirmed = async () => {
    try {
      await chrome.storage.local.clear();
      await chrome.storage.session.clear();
      await signOut();
      setClearLocalDataError(null);
      setClearLocalDataOpen(false);
    } catch {
      setClearLocalDataError('Could not finish reset. Try again.');
    }
  };

  const desktopColor = desktopStatusTextClass(desktop.transport, desktop.health);
  const engineHealth = engineHealthState(desktop.health);
  const canCheckForUpdate = typeof chrome.runtime.requestUpdateCheck === 'function';
  const loginApiAvailability = browserLoginApiAvailability();

  const checkForExtensionUpdate = () => {
    if (typeof chrome.runtime.requestUpdateCheck !== 'function') return;
    setExtensionUpdate({ kind: 'idle' });
    try {
      chrome.runtime.requestUpdateCheck((status, details) => {
        if (chrome.runtime.lastError) {
          setExtensionUpdate({ kind: 'error' });
          return;
        }
        if (status === 'update_available') {
          setExtensionUpdate({
            kind: 'update_available',
            ...(details?.version ? { version: details.version } : {}),
          });
          return;
        }
        if (status === 'no_update' || status === 'throttled') {
          setExtensionUpdate({ kind: status });
          return;
        }
        setExtensionUpdate({ kind: 'error' });
      });
    } catch {
      setExtensionUpdate({ kind: 'error' });
    }
  };

  return (
    <div className="flex h-full flex-col">
      <div className="flex h-9 shrink-0 items-center px-3">
        <span className="text-sm font-medium">Settings</span>
      </div>

      <div className="flex-1 overflow-y-auto">
        <div className="space-y-3 px-3 pb-3">
          <Collapsible label="Account">
            <Card>
              <Row label="Email" value={user?.email ?? '—'} mono />
              {user?.full_name && <Row label="Name" value={user.full_name} />}
              {user && isAdmin && <Row label="Role" value={<Badge>admin</Badge>} />}
            </Card>
          </Collapsible>

          <Collapsible label="Organization" defaultOpen={org.mustChoose}>
            <Card>
              {user && (
                <div className="px-3 py-2">
                  <ArchiveFilter
                    value={orgArchiveFilter}
                    onValueChange={setOrgArchiveFilter}
                    size="sm"
                    aria-label="Filter organizations by archive status"
                  />
                </div>
              )}
              {org.error ? (
                <Row
                  label="Organizations"
                  value={<span className="text-destructive">{org.error}</span>}
                />
              ) : org.loading ? (
                <Row label="Organization" value="Loading…" />
              ) : !user ? (
                <Row label="Organization" value="Sign in to choose" />
              ) : org.organizations.length === 0 ? (
                <Row
                  label="Organization"
                  value={
                    orgArchiveFilter === 'active'
                      ? 'No active organization to choose. Show archived to inspect archived memberships.'
                      : 'No organizations match this archive filter.'
                  }
                />
              ) : activeOrganizations.length === 0 ? (
                <Row
                  label="Acting as"
                  value={
                    org.active
                      ? `Working in ${org.active.name}. Archived organizations are view-only; show active organizations to switch.`
                      : 'Archived organizations are view-only. Show active organizations to choose where new work goes.'
                  }
                />
              ) : (
                <ControlRow
                  label="Acting as"
                  control={
                    <PillSelect
                      value={org.active?.id ?? NONE}
                      onChange={(v) => {
                        if (v === NONE) return;
                        void org.choose(v).catch((err: unknown) => {
                          setOrgError(err instanceof Error ? err.message : String(err));
                        });
                      }}
                      placeholder="Choose…"
                      options={[
                        ...(org.active ? [] : [{ value: NONE, label: 'Choose…' }]),
                        ...activeOrganizations.map((o) => ({
                          value: o.id,
                          label: o.name,
                        })),
                      ]}
                    />
                  }
                />
              )}
              {archivedOrganizations.length > 0 && (
                <div className="space-y-1 px-3 py-2 text-xs">
                  {archivedOrganizations.map((organization) => (
                    <div key={organization.id}>
                      <span className="font-medium">{organization.name}</span>
                      <span className="ml-2 text-muted-foreground">Archived · view only</span>
                    </div>
                  ))}
                  <OpenUrl
                    url={`${ENV.FRONTEND_URL}/organizations`}
                    label="Open Organizations to restore an archived organization"
                  />
                </div>
              )}
              {orgError && (
                <Row label="" value={<span className="text-destructive">{orgError}</span>} />
              )}
            </Card>
          </Collapsible>

          <Collapsible label="Appearance">
            <Card>
              <ControlRow
                label="Theme"
                control={
                  <PillSelect
                    value={settings.theme}
                    onChange={(v) => settings.setTheme(v as typeof settings.theme)}
                    options={[
                      { value: 'system', label: 'System' },
                      { value: 'light', label: 'Light' },
                      { value: 'dark', label: 'Dark' },
                    ]}
                  />
                }
              />
            </Card>
          </Collapsible>

          {settingsSaveState === 'error' && (
            <div
              role="alert"
              className="flex items-center justify-between gap-2 px-3 text-xs text-destructive"
            >
              <span>Could not save preferences. Retry before closing Settings.</span>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => void retrySettingsSave()}
              >
                Retry save
              </Button>
            </div>
          )}

          <Collapsible label="Chat">
            <Card>
              <ControlRow
                label="Default agent"
                control={
                  /* THE ONE agent picker — the same rows, order and filters
                     the chat surfaces show, so a person's Settings choice and
                     their in-chat choice can never disagree about what
                     exists. */
                  org.active ? (
                    <AgentListDropdown
                      consumerId="extend.settings.default-agent"
                      activeAgentId={settings.defaultAgentId}
                      onSelect={(id) => settings.setDefaultAgentId(id)}
                      defaultMandateKey={DEFAULT_CHAT_MANDATE_KEY}
                      compact
                    />
                  ) : (
                    <span className="text-xs text-muted-foreground">
                      Choose an organization above
                    </span>
                  )
                }
              />
              <ControlRow
                label="Default mode"
                control={
                  <PillSelect
                    value={settings.defaultPermissionMode}
                    onChange={(v) =>
                      settings.setDefaultPermissionMode(v as typeof settings.defaultPermissionMode)
                    }
                    options={[
                      { value: 'ask', label: 'Ask before acting' },
                      { value: 'act', label: 'Act without asking' },
                    ]}
                  />
                }
              />
              <ControlRow
                label="Default speed"
                hint="coming soon"
                control={
                  <PillSelect
                    value={settings.defaultChatSpeed}
                    onChange={(v) =>
                      settings.setDefaultChatSpeed(v as typeof settings.defaultChatSpeed)
                    }
                    options={[
                      { value: 'fast', label: 'Fast' },
                      { value: 'thinking', label: 'Thinking' },
                    ]}
                  />
                }
              />
            </Card>
          </Collapsible>

          <Collapsible label="Privacy">
            <Card>
              <ControlRow
                label="Share page identity & email content"
                hint="lets the agent see your visible username on sites and Gmail subjects/excerpts"
                control={
                  <Switch
                    aria-label="Share page identity & email content"
                    checked={settings.sharePageIdentity}
                    onCheckedChange={settings.setSharePageIdentity}
                  />
                }
              />
              <ControlRow
                label="Offer to save logins to the Vault"
                hint="after you sign in to a site, ask whether to save that login — nothing is saved without your click"
                control={
                  <Switch
                    aria-label="Offer to save logins to the Vault"
                    checked={settings.captureLoginsEnabled}
                    onCheckedChange={settings.setCaptureLoginsEnabled}
                  />
                }
              />
              <ControlRow
                label="Offer saved logins on sign-in forms"
                hint="allows matching saved logins; choose where suggestions appear below"
                control={
                  <Switch
                    aria-label="Offer saved logins on sign-in forms"
                    checked={settings.offerSavedLoginsEnabled}
                    onCheckedChange={settings.setOfferSavedLoginsEnabled}
                  />
                }
              />
              <ControlRow
                label="Show password suggestions on websites"
                hint="Off keeps websites quiet. Pin Matrx to see toolbar assistance, then open Vault to review Save or Update; nothing is saved automatically."
                control={
                  <Switch
                    aria-label="Show password suggestions on websites"
                    checked={settings.credentialAssistancePresentation === 'on_page'}
                    onCheckedChange={(checked) =>
                      settings.setCredentialAssistancePresentation(checked ? 'on_page' : 'quiet')
                    }
                  />
                }
              />
              <NeverCaptureSites />
            </Card>
          </Collapsible>

          <Collapsible label="Scrape">
            <Card>
              <ControlRow
                label="Deep clean"
                hint="coming soon"
                control={
                  <Switch
                    aria-label="Deep clean"
                    checked={settings.scrapeDeepClean}
                    onCheckedChange={settings.setScrapeDeepClean}
                  />
                }
              />
              <ControlRow
                label="Auto-scrape on load"
                hint="capture page content in the background after each load"
                control={
                  <Switch
                    aria-label="Auto-scrape on load"
                    checked={settings.scrapeAutoOnLoad}
                    onCheckedChange={settings.setScrapeAutoOnLoad}
                  />
                }
              />
              <ControlRow
                label="Auto-scrape mode"
                hint="Scroll & capture loads lazy content first (slower)"
                control={
                  <PillSelect
                    value={settings.scrapeAutoMode}
                    onChange={(v) =>
                      settings.setScrapeAutoMode(v as typeof settings.scrapeAutoMode)
                    }
                    options={[
                      { value: 'capture', label: 'Capture' },
                      { value: 'scroll-capture', label: 'Scroll & capture' },
                    ]}
                  />
                }
              />
            </Card>
          </Collapsible>

          <Collapsible label="Data" defaultOpen={false}>
            <EmptyCard>No options yet</EmptyCard>
          </Collapsible>

          <Collapsible label="SEO" defaultOpen={false}>
            <EmptyCard>No options yet</EmptyCard>
          </Collapsible>

          <Collapsible label="Desktop bridge">
            <Card>
              <Row
                label="Status"
                value={
                  <span className={desktopColor}>
                    {formatDesktopConnectionLabel(desktop.transport, desktop.health)}
                  </span>
                }
              />
              {desktop.transport !== 'none' && engineHealth !== 'ok' && (
                <Row
                  label="Engine health"
                  value={
                    <span className={desktopColor}>
                      {engineHealth === 'degraded' ? 'Degraded' : 'Failed services'}
                    </span>
                  }
                />
              )}
              {desktop.health?.degraded?.length ? (
                <Row label="Degraded" value={desktop.health.degraded.join(', ')} mono />
              ) : null}
              {desktop.health?.failed?.length ? (
                <Row label="Failed" value={desktop.health.failed.join(', ')} mono />
              ) : null}
              {desktop.health?.version && (
                <Row label="Version" value={`matrx-local v${desktop.health.version}`} mono />
              )}
              {desktop.transport !== 'native' && (
                <p className="px-3.5 pt-2 text-xs text-muted-foreground">
                  Pairing is automatic when the Matrx desktop app runs on this computer. The code
                  below is only needed to pair with a desktop app on another machine — copy it from
                  that app&apos;s Settings → Bridge Test → Extension pairing.
                </p>
              )}
              {desktop.transport !== 'native' && (
                <div className="flex items-center gap-2 px-3.5 py-2">
                  <Input
                    value={pairTokenInput}
                    onChange={(e) => {
                      pairInputRevision.current += 1;
                      setPairTokenInput(e.target.value);
                      setPairTokenError(null);
                    }}
                    placeholder="Pair code"
                    className="h-7 rounded-full border-0 bg-secondary focus-visible:ring-1"
                  />
                  <Button
                    size="sm"
                    className="h-7 rounded-full px-3"
                    disabled={!pairTokenInput.trim()}
                    onClick={async () => {
                      if (pairTokenInput.trim()) {
                        const submittedInput = pairTokenInput;
                        const revision = ++pairInputRevision.current;
                        try {
                          await serializeStorageWrite(pairWritePending, () =>
                            setPairToken(submittedInput.trim()),
                          );
                          if (pairInputRevision.current === revision) {
                            setPairTokenInput('');
                            setPairTokenError(null);
                          }
                        } catch {
                          if (pairInputRevision.current === revision)
                            setPairTokenError('Could not save pair code. Try again.');
                        }
                      }
                    }}
                  >
                    Pair
                  </Button>
                </div>
              )}
              {pairTokenError && (
                <div className="px-3.5 pb-2 text-[11px] text-red-600 dark:text-red-400">
                  {pairTokenError}
                </div>
              )}
              {desktop.transport === 'http' && (
                <ActionRow
                  label="Forget pair code"
                  onClick={() => {
                    void confirmDestructive({
                      title: 'Forget the desktop pair code?',
                      consequence:
                        'This browser is unpaired from the Matrx desktop app: local tools and desktop files stop working here until you pair again. Nothing on the desktop is deleted.',
                      alternative:
                        'If the desktop app is just offline, cancel — the code still works when it comes back.',
                      confirmLabel: 'Forget pair code',
                      run: () => serializeStorageWrite(pairWritePending, clearPairToken),
                    })
                      .then((confirmed) => {
                        if (confirmed) setPairTokenError(null);
                      })
                      .catch(() => setPairTokenError('Could not forget pair code. Try again.'));
                  }}
                />
              )}
              <div className="flex items-center gap-2 px-3.5 py-2">
                <span className="shrink-0 text-sm">Local engine port</span>
                <Input
                  inputMode="numeric"
                  pattern="[0-9]*"
                  value={enginePortInput}
                  onChange={(e) => {
                    enginePortInputRevision.current += 1;
                    setEnginePortInput(e.target.value.replace(/[^0-9]/g, ''));
                  }}
                  placeholder="auto"
                  className="h-7 w-20 rounded-full border-0 bg-secondary text-right focus-visible:ring-1"
                />
                <Button
                  size="sm"
                  className="h-7 rounded-full px-3"
                  onClick={() => void handleSaveEnginePort()}
                >
                  {enginePortSaved === null ? 'Set' : 'Save'}
                </Button>
                {enginePortSaved !== null && (
                  <span className="text-[10px] uppercase tracking-wider text-muted-foreground/70">
                    override
                  </span>
                )}
              </div>
              {enginePortError && (
                <div className="px-3.5 pb-2 text-[11px] text-red-600 dark:text-red-400">
                  {enginePortError}
                </div>
              )}
            </Card>
          </Collapsible>

          {isAdmin && (
            <Collapsible label="Advanced agent capabilities" defaultOpen={false}>
              <AdvancedAgentCapabilities />
            </Collapsible>
          )}

          <Collapsible label="Data & reset">
            <Card>
              <ActionRow
                label="Clear local data on this device"
                icon={<Trash2 className="size-3.5" />}
                destructive
                onClick={() => {
                  setClearLocalDataError(null);
                  setClearLocalDataOpen(true);
                }}
              />
            </Card>
          </Collapsible>

          <ConfirmDialog
            open={clearLocalDataOpen}
            onOpenChange={(next) => {
              if (!next) setClearLocalDataOpen(false);
            }}
            title="Clear local data?"
            description={
              <>
                <span className="block">
                  Clear all locally cached extension data on this device?
                </span>
                <span className="mt-2 block">
                  You will be signed out. Your chats, captures and patterns saved on the server are
                  NOT affected.
                </span>
                {clearLocalDataError && (
                  <span className="mt-2 block text-destructive">{clearLocalDataError}</span>
                )}
              </>
            }
            confirmLabel="Clear & sign out"
            variant="destructive"
            onConfirm={() => void handleClearLocalDataConfirmed()}
          />

          <Collapsible label="About" defaultOpen={false}>
            <Card>
              <Row label="Browser" value={installedBrowserLabel()} />
              <Row label="Installed version" value={chrome.runtime.getManifest().version} mono />
              <Row label="Extension ID" value={chrome.runtime.id} mono />
              <Row
                label="Browser APIs for saved logins"
                value={
                  loginApiAvailability === 'available' ? (
                    <span className="text-emerald-600 dark:text-emerald-400">Available</span>
                  ) : (
                    <span className="text-destructive">Unavailable</span>
                  )
                }
              />
              {loginApiAvailability === 'available' ? (
                <p className="px-3.5 pb-2 text-xs text-muted-foreground">
                  Vault checks whether saved logins can be used for this browser and site when you
                  choose one.
                </p>
              ) : (
                <p className="px-3.5 pb-2 text-xs text-muted-foreground">
                  Reload or reinstall Matrx Extend in a supported browser to use saved logins.
                </p>
              )}
              {canCheckForUpdate ? (
                <div className="px-3.5 py-2">
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-7 rounded-full px-3"
                    onClick={checkForExtensionUpdate}
                  >
                    Check for extension update
                  </Button>
                </div>
              ) : (
                <p className="px-3.5 py-2 text-xs text-muted-foreground">
                  Updates are managed by your browser. Open its Extensions page, find Matrx Extend,
                  and use its update controls.
                </p>
              )}
              {updateStatusCopy(extensionUpdate) && (
                <p className="px-3.5 pb-2 text-xs text-muted-foreground">
                  {updateStatusCopy(extensionUpdate)}
                </p>
              )}
            </Card>
          </Collapsible>
        </div>
      </div>

      <div className="shrink-0 px-3 pb-3 pt-1">
        {user ? (
          <Button
            variant="ghost"
            onClick={signOut}
            className="w-full rounded-full text-destructive hover:bg-destructive/10 hover:text-destructive"
          >
            <LogOut className="size-3.5" /> Sign out
          </Button>
        ) : (
          <Button onClick={() => void signIn()} className="w-full rounded-full">
            <LogIn className="size-3.5" /> Sign in
          </Button>
        )}
      </div>
    </div>
  );
}

function Card({ children }: { children: React.ReactNode }) {
  return (
    <div className="overflow-hidden rounded-xl border bg-card">
      <div className="divide-y divide-border/60">{children}</div>
    </div>
  );
}

